import React, { useState } from "react";
import { supabase } from "../supabaseClient";
import { useNavigate } from "react-router-dom";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  async function handleLogin(e) {
    e.preventDefault();

    const { error, data } = await supabase.auth.signInWithPassword({
      email,
      password,
    });

    if (error) {
      alert(error.message);
    } else {
      alert("התחברת בהצלחה!");

      // בדוק את המשתמש אחרי ההתחברות
      const {
        data: { user },
        error: userError,
      } = await supabase.auth.getUser();

      console.log("User Data:", user); // הוסף את הלוג הזה
      console.log("User Error:", userError); // הוסף את הלוג הזה

      if (userError) {
        alert("לא הצלחנו לזהות את המשתמש.");
      } else if (user && user.email === "dinalevitan123@gmail.com") {
        console.log("Navigating to /admin"); // הוסף את הלוג הזה
        navigate("/admin"); // מעביר ל- /admin
      } else {
        alert("אין לך הרשאות גישה לעמוד זה.");
      }
    }
  }

  return (
    <form onSubmit={handleLogin} style={{ marginTop: "50px" }}>
      <input
        type="email"
        placeholder="אימייל"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
      />
      <input
        type="password"
        placeholder="סיסמה"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
      />
      <button type="submit">התחבר</button>
    </form>
  );
}
