import Homepage from "./pages/Homepage";
import Refund from "./pages/Refund";
import QuestionsAndAnswers from "./pages/QuestionsAndAnswers";
import Articles from "./pages/Articles";
import Admin from "./pages/Admin";
import Login from "./pages/Login";
import ProtectedRoute from "./components/ProtectedRoute";
import ContactPage from "./pages/ContactPage";
import Recommendations from "./pages/Recommendations";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";

import Calendar from "./pages/Calendar";
import FirstArticle from "./pages/FirstArticle";
import SecondArticle from "./pages/SecondArticle";

function App() {
  return (
    <Router>
      <Routes>
        <Route index element={<Homepage />} />
        <Route path="questionsAndAnswers" element={<QuestionsAndAnswers />} />
        <Route path="Recommendations" element={<Recommendations />} />
        <Route path="Articles" element={<Articles />} />
        <Route path="contact" element={<ContactPage />} />
        <Route path="calendar" element={<Calendar />} />
        <Route path="Refund" element={<Refund />} />
        <Route
          path="Admin"
          element={
            <ProtectedRoute>
              <Admin />
            </ProtectedRoute>
          }
        />
        <Route path="FirstArticle" element={<FirstArticle />} />
        <Route path="Login" element={<Login />} />
        <Route path="SecondArticle" element={<SecondArticle />} />
      </Routes>
    </Router>
  );
}

export default App;
