import React, { useState, useEffect } from "react";
import { supabase } from "../supabaseClient";
import FullCalendar from "@fullcalendar/react";
import dayGridPlugin from "@fullcalendar/daygrid";
import timeGridPlugin from "@fullcalendar/timegrid";
import interactionPlugin from "@fullcalendar/interaction";
import allLocales from "@fullcalendar/core/locales-all";
import styles from "../components/CourseCalendar.module.css";

export default function CourseCalendar() {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    const fetchEvents = async () => {
      const { data, error } = await supabase
        .from("derech-aneshima")
        .select("id, title, start, description");

      if (error) {
        console.error("Error fetching events:", error.message);
        return;
      }

      // ודא שהתאריכים בפורמט נכון
      const formattedEvents = data.map((event) => ({
        id: event.id,
        title: event.title,
        start: new Date(event.start).toISOString().split("T")[0], // שמירה רק על התאריך ללא הזמן
        description: event.description,
      }));

      setEvents(formattedEvents);
    };

    fetchEvents();
  }, []);

  const renderEventContent = (eventInfo) => (
    <div className={styles.Pcontainer}>
      <b>{eventInfo.timeText}</b>
      <p>{eventInfo.event.title}</p>
      {eventInfo.event.extendedProps.description && (
        <p>{eventInfo.event.extendedProps.description}</p>
      )}
    </div>
  );

  return (
    <div className={styles.container}>
      <FullCalendar
        plugins={[dayGridPlugin, timeGridPlugin, interactionPlugin]}
        initialView="dayGridMonth"
        locales={allLocales}
        locale="he"
        direction="rtl"
        headerToolbar={{
          start: "",
          center: "title",
          end: "next today",
        }}
        events={events}
        eventContent={renderEventContent}
        height="110vh"
        fixedWeekCount={false}
      />
    </div>
  );
}
